const COLORS={Twink:'#ff4db8',Cub:'#ffc14a',Otter:'#57e38c',Independent:'#7a82ff'};
const $=s=>document.querySelector(s);function hotkeyTargetIsInteractive(t){return !!(t&&t.closest&&t.closest('input,select,textarea,button,a,[contenteditable="true"],[role="button"],[role="textbox"],[role="combobox"],[role="slider"],[tabindex]:not([tabindex="-1"])'))}
function storageGet(k,fallback='[]'){try{return localStorage.getItem(k)||fallback}catch{return fallback}}
function storageSet(k,v){try{localStorage.setItem(k,v)}catch{}}
function loadBattlePrefs(){try{return JSON.parse(storageGet('gaydex-battle-v1','{}'))||{}}catch{return {}}}
function saveBattlePrefs(){storageSet('gaydex-battle-v1',JSON.stringify({scene:battleState.scene,intro:battleState.intro,arenaEffects:battleState.arenaEffects,speed:battleState.speed,sfx:battleState.sfx,balanced:battleState.balanced,cpuB:battleState.cpuB,sandboxDuel:!battleState.cpuB,cpuSkill:battleState.cpuSkill,fxMode:battleState.fxMode,motionMode:battleState.motionMode,matchA:battleState.idA,matchB:battleState.idB}))}

let storedSelected=storageGet('gaydex-selected','twink');const state={selected:GAYDEX.some(x=>x.id===storedSelected)?storedSelected:'twink',seen:new Set(JSON.parse(storageGet('gaydex-seen'))),favs:new Set(JSON.parse(storageGet('gaydex-favs'))),compare:new Set(JSON.parse(storageGet('gaydex-compare'))),perf:false,atlasOpen:true};
function entry(id){return GAYDEX.find(x=>x.id===id)}
function save(){storageSet('gaydex-selected',state.selected);storageSet('gaydex-seen',JSON.stringify([...state.seen]));storageSet('gaydex-favs',JSON.stringify([...state.favs]));storageSet('gaydex-compare',JSON.stringify([...state.compare]))}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function setImageSource(el,src,key){if(!el)return;if(el.dataset.assetKey!==key){el.dataset.assetKey=key;el.src=src}}
function lineColor(e){return COLORS[e.line]||'#42e7ff'}
const statNames=['Youth','Power','Hair','Maturity','Vibe'];
const ATLAS_LINES=[
 {label:'Twink',hint:'lean · smooth',ids:['twink','twank','twunk','mega-twunk'],variant:'elder-twink'},
 {label:'Cub',hint:'soft · stocky',ids:['cub','cob','bear','mega-bear'],variant:'polar-bear'},
 {label:'Otter',hint:'lean · hairy',ids:['twink-otter','otter','mature-otter','mega-otter'],variant:'silver-otter'},
 {label:'Wild',hint:'side species',ids:['jock','daddy','silver-daddy','average-guy']}
];
function atlasNode(id){let e=entry(id);return `<button type="button" class="atlas-node ${id===state.selected?'active':''}" style="--nodeColor:${lineColor(e)}" data-atlas="${id}" aria-label="Open ${esc(e.name)} from Lineage Atlas"><img src="${e.img}" alt="" loading="lazy" decoding="async"><span>${esc(e.name)}</span><em>${esc(e.stage)} · ${esc(e.designation)}</em></button>`}
function renderAtlas(){let body=$('#atlasBody');if(!body)return;body.hidden=!state.atlasOpen;$('#atlasToggle').setAttribute('aria-expanded',String(state.atlasOpen));$('#atlasToggle').textContent=state.atlasOpen?'Collapse atlas':'Open atlas';if(!state.atlasOpen)return;if(!body.dataset.built){body.innerHTML=ATLAS_LINES.map(row=>`<div class="atlas-row"><div class="atlas-label"><strong>${row.label}</strong><small>${row.hint}</small></div><div class="atlas-track">${row.ids.map((id,i)=>`${atlasNode(id)}${i<row.ids.length-1?'<span class="atlas-arrow" aria-hidden="true">→</span>':''}`).join('')}${row.variant?`<span class="atlas-branch">VARIANT ↳</span>${atlasNode(row.variant)}`:''}</div></div>`).join('');body.dataset.built='1';body.querySelectorAll('[data-atlas]').forEach(b=>b.addEventListener('click',()=>selectEntry(b.dataset.atlas,true)))}syncAtlasSelection()}let atlasSelected='';function syncAtlasSelection(){if(atlasSelected){document.querySelector(`[data-atlas="${CSS.escape(atlasSelected)}"]`)?.classList.remove('active')}document.querySelector(`[data-atlas="${CSS.escape(state.selected)}"]`)?.classList.add('active');atlasSelected=state.selected}function scheduleAtlas(){let run=()=>renderAtlas();if('requestIdleCallback' in window)requestIdleCallback(run,{timeout:220});else setTimeout(run,60)}
function renderCompare(){let dock=$('#compareDock');if(!dock)return;let ids=[...state.compare].filter(id=>entry(id)).slice(0,3);if(ids.length!==state.compare.size)state.compare=new Set(ids);$('#compareCount').textContent=`${ids.length}/3`;dock.hidden=!ids.length;let cb=$('#compareBattle');if(cb){cb.disabled=ids.length<2;cb.textContent=ids.length<2?'⚔ Pin 2 to battle':'⚔ Battle first two'}if(!ids.length){$('#compareGrid').innerHTML='';return}$('#compareGrid').innerHTML=ids.map(id=>{let e=entry(id);return `<article class="compare-card" style="--nodeColor:${lineColor(e)}"><img src="${e.img}" alt="Illustrated ${esc(e.name)}" loading="lazy" decoding="async"><div><h3>${esc(e.name)}</h3><div class="compare-meta">${esc(e.line)} · ${esc(e.designation)} · ${esc(e.rarity)}</div>${e.stats.map((v,i)=>`<div class="mini-stat"><span>${statNames[i]}</span><span class="mini-track"><i style="width:${v}%"></i></span><strong>${v}</strong></div>`).join('')}</div><button type="button" class="compare-remove" data-compare-remove="${e.id}" aria-label="Remove ${esc(e.name)} from Compare Deck">×</button></article>`}).join('');document.querySelectorAll('[data-compare-remove]').forEach(b=>b.addEventListener('click',()=>toggleCompare(b.dataset.compareRemove)))}
function toggleCompare(id){let evicted=null;if(state.compare.has(id)){state.compare.delete(id)}else{if(state.compare.size>=3){evicted=[...state.compare][0];state.compare.delete(evicted)}state.compare.add(id)}save();renderCompare();if(evicted)document.querySelector(`#dexGrid .card[data-id="${CSS.escape(evicted)}"]`)?.classList.remove('comparing');document.querySelector(`#dexGrid .card[data-id="${CSS.escape(id)}"]`)?.classList.toggle('comparing',state.compare.has(id));let active=state.compare.has(state.selected);$('#compareBtn')?.setAttribute('aria-pressed',String(active));if($('#compareBtn'))$('#compareBtn').textContent=active?'⊖ Remove compare':'⊕ Compare'}
function renderLineageGhosts(e){let i=e.evo.indexOf(e.id),prev=i>0?entry(e.evo[i-1]):null,next=i>=0&&i<e.evo.length-1?entry(e.evo[i+1]):null;let draw=(sel,x,label)=>{let el=$(sel);if(!el)return;if(!x){el.innerHTML='';return}el.innerHTML=`<img src="${x.img}" alt="" loading="lazy" decoding="async"><small>${label}: ${esc(x.name)}</small>`};draw('#lineagePrev',prev,'PREV');draw('#lineageNext',next,'NEXT')}let lineageGhostTimer=0;function scheduleLineageGhosts(e){clearTimeout(lineageGhostTimer);let id=e.id;lineageGhostTimer=setTimeout(()=>{if(state.selected===id)renderLineageGhosts(e)},70)}let lastScan=0;function pulseScan(){let now=performance.now();if(now-lastScan<180||matchMedia('(prefers-reduced-motion: reduce)').matches)return;lastScan=now;let beam=$('.scan-sweep');if(!beam?.animate)return;beam.getAnimations().forEach(a=>a.cancel());beam.animate([{transform:'translateY(-80%)',opacity:0},{opacity:.9,offset:.1},{transform:'translateY(430%)',opacity:0}],{duration:620,easing:'cubic-bezier(.2,.7,.2,1)'})}

function renderGrid(){let q=$('#search').value.trim().toLowerCase(),line=$('#lineFilter').value,stat=$('#statusFilter').value;let list=GAYDEX.filter(e=>(line==='all'||e.line===line)&&(stat==='all'||e.designation===stat)&&(!q||[e.name,e.desc,e.build,e.hair,e.age,e.vibe,e.line,e.designation,...e.traits].join(' ').toLowerCase().includes(q)));$('#dexGrid').innerHTML=list.length?list.map(e=>`<button type="button" class="card ${e.id===state.selected?'selected':''} ${state.seen.has(e.id)?'seen':''} ${state.compare.has(e.id)?'comparing':''}" style="--cardColor:${lineColor(e)}" data-id="${e.id}" aria-label="Open ${esc(e.name)}"><span class="seen-dot"></span><img src="${e.img}" alt="Illustrated ${esc(e.name)}" loading="lazy" decoding="async"><div class="card-body"><div class="number">#${String(e.num).padStart(3,'0')} · ${esc(e.stage)}</div><h3>${esc(e.name)}</h3><div class="micro"><span>${esc(e.line)}</span><span>${esc(e.rarity)}</span></div></div></button>`).join(''):'<div class="empty">No specimens matched. Reduce the taxonomy until the gays reappear.</div>';document.querySelectorAll('.card').forEach(b=>b.addEventListener('click',()=>selectEntry(b.dataset.id,true)))}
function designationClass(d){return d==='House coinage'?'designation-house':d.includes('mega')||d.includes('Mega')?'designation-mega':''}function refreshGridState(){let old=$('#dexGrid .card.selected');old?.classList.remove('selected');let cur=document.querySelector(`#dexGrid .card[data-id="${CSS.escape(state.selected)}"]`);cur?.classList.add('selected','seen')}
function renderEntry(e,trigger3d=true){if(trigger3d&&typeof battleState!=='undefined'&&battleState.mirrorHero){battleState.mirrorHero=false;let b=$('#battleMirror');if(b){b.setAttribute('aria-pressed','false');b.textContent='↥ Mirror battle'}}$('#stage')?.classList.remove('battle-active');if($('#battleStageFallback'))$('#battleStageFallback').hidden=true;state.selected=e.id;state.seen.add(e.id);save();let pct=Math.round(state.seen.size/GAYDEX.length*100);$('#seenCount').textContent=state.seen.size;$('#seenPct').textContent=`${pct}%`;$('#favCount').textContent=state.favs.size;$('#stageNum').textContent=`#${String(e.num).padStart(3,'0')} // ${e.stage.toUpperCase()}`;$('#stageName').textContent=e.name.toUpperCase();$('#fallbackPortrait').src=e.img;$('#fallbackPortrait').alt=`Illustrated ${e.name}`;$('#entryName').textContent=e.name;$('#entryDesc').textContent=e.desc;document.documentElement.style.setProperty('--lineColor',lineColor(e));$('#eyebrow').innerHTML=`<span class="tag">${esc(e.line)} line</span><span class="tag ${designationClass(e.designation)}">${esc(e.designation)}</span><span class="tag">${esc(e.rarity)}</span>`;$('#facts').innerHTML=[['Build',e.build],['Body hair',e.hair],['Life stage',e.age],['Vibe',e.vibe]].map(x=>`<div class="fact"><small>${x[0]}</small><strong>${esc(x[1])}</strong></div>`).join('');$('#stats').innerHTML=e.stats.map((v,i)=>`<div class="stat"><span>${statNames[i]}</span><div class="track"><div class="fill" style="width:${v}%"></div></div><strong>${v}</strong></div>`).join('');$('#evoPath').innerHTML=e.evo.map((id,i)=>{let x=entry(id);return `<button type="button" class="evo-node ${id===e.id?'active':''}" data-evo="${id}">${esc(x.name)}</button>${i<e.evo.length-1?'<span class="arrow">→</span>':''}`}).join('');document.querySelectorAll('[data-evo]').forEach(b=>b.addEventListener('click',()=>selectEntry(b.dataset.evo,true)));let mb=$('#megaBtn');mb.disabled=!e.mega&&e.stage==='Mega';mb.textContent=e.stage==='Mega'?'✦ Mega Active':e.mega?'✦ Mega Shift':'✦ No Mega Route';mb.dataset.mega=e.mega||'';let f=state.favs.has(e.id);$('#favBtn').setAttribute('aria-pressed',String(f));$('#favBtn').textContent=f?'♥ Favorited':'♡ Favorite';let cmp=state.compare.has(e.id);$('#compareBtn').setAttribute('aria-pressed',String(cmp));$('#compareBtn').textContent=cmp?'⊖ Remove compare':'⊕ Compare';scheduleLineageGhosts(e);refreshGridState();if(trigger3d)renderAtlas();else scheduleAtlas();if(trigger3d)pulseScan();if(trigger3d&&window.gayDex3D)window.gayDex3D.setEntry(e);}
function selectEntry(id,scroll=false){let e=entry(id);if(!e)return;renderEntry(e,true);if(scroll&&innerWidth<981)$('#stage').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}
$('#randomBtn').addEventListener('click',()=>{let pool=GAYDEX.filter(e=>e.stage!=='Mega');selectEntry(pool[Math.floor(Math.random()*pool.length)].id,true);if(window.gayDex3D)window.gayDex3D.burst(.45)});
$('#megaBtn').addEventListener('click',()=>{let e=entry(state.selected);if(e.stage==='Mega')return;if(e.mega){selectEntry(e.mega,false);$('#stage').classList.remove('burst');void $('#stage').offsetWidth;$('#stage').classList.add('burst');if(window.gayDex3D)window.gayDex3D.burst(1)}});
$('#favBtn').addEventListener('click',()=>{let id=state.selected;state.favs.has(id)?state.favs.delete(id):state.favs.add(id);save();renderEntry(entry(id),false)});$('#compareBtn').addEventListener('click',()=>toggleCompare(state.selected));$('#clearCompare').addEventListener('click',()=>{state.compare.clear();save();renderCompare();document.querySelectorAll('#dexGrid .card.comparing').forEach(x=>x.classList.remove('comparing'));renderEntry(entry(state.selected),false)});$('#compareBattle').addEventListener('click',()=>{let ids=[...state.compare].filter(id=>entry(id)).slice(0,2);if(ids.length<2)return;let a=entry(ids[0]),b=entry(ids[1]);$('#battleLineA').value=a.line;populateBattleStages('A',a.line,a.id);$('#battleStageA').value=a.id;$('#battleLineB').value=b.line;populateBattleStages('B',b.line,b.id);$('#battleStageB').value=b.id;$('#battlePlayerPick').value=a.id;resetBattle();$('#battleTerminal').scrollIntoView({behavior:battleReducedMotion()?'auto':'smooth',block:'start'});battleAnnounce('COMPARE → BATTLE',`${a.name} vs ${b.name}`,'neutral')});$('#atlasToggle').addEventListener('click',()=>{state.atlasOpen=!state.atlasOpen;renderAtlas()});
$('#shareLikeBtn').addEventListener('click',async()=>{let name=entry(state.selected).name;try{await navigator.clipboard.writeText(name);$('#shareLikeBtn').textContent='✓ Copied';setTimeout(()=>$('#shareLikeBtn').textContent='⌁ Copy entry name',900)}catch{$('#shareLikeBtn').textContent=name;setTimeout(()=>$('#shareLikeBtn').textContent='⌁ Copy entry name',1200)}});
['search','lineFilter','statusFilter'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',renderGrid));$('#clearBtn').addEventListener('click',()=>{$('#search').value='';$('#lineFilter').value='all';$('#statusFilter').value='all';renderGrid()});
