    battleSpawnFx(s,e.type||'force',special);if(readLock)battleSpawnFx(s,'insight',true);
    battleSound(readLock?'readlock':e.type||'force',special||readLock);
    window.gayDexBattle3D?.pulse?.(readLock?'#42e7ff':battleColorFor(battleState.match[s]),readLock?1.15:special?1:.55);
    await battleDelay(readLock?190:140);def.classList.add(hitCls);battleFlash(s,readLock?'#42e7ff':battleColorFor(battleState.match[s]));
    theatre.classList.remove('camera-hit');void theatre.offsetWidth;theatre.classList.add('camera-hit');
