    battleSound(e.predicted?'readlock':'insight',!!e.predicted);window.gayDexBattle3D?.pulse?.(e.side==='a'?'#ff4db8':'#42e7ff',e.predicted?1.1:.75);await battleDelay(e.predicted?360:240);return;
