  saveBattlePrefs();
  const seed=preserveSeed&&battleState.match?battleState.match.seed:hashSeed(`${battleState.idA}|${battleState.idB}|${battleState.balanced}|${battleState.scene}|${battleSeedCounter++}`);
  battleState.match=makeReadBattleMatch(entry(battleState.idA),entry(battleState.idB),battleState.balanced,seed);
  warmBattleAssetsForMatch(battleState.match);applyBattleOpener(battleState.match);
